import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Analytics & Observability Components","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/components/analytics-observability.md","filePath":"frontend/components/analytics-observability.md"}`),a={name:`frontend/components/analytics-observability.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="analytics-observability-components" tabindex="-1">Analytics &amp; Observability Components <a class="header-anchor" href="#analytics-observability-components" aria-label="Permalink to &quot;Analytics &amp; Observability Components&quot;">​</a></h1><p>To keep the AI platform transparent and performant, several components are dedicated purely to data visualization.</p><h2 id="analyticschart-jsx" tabindex="-1"><code>AnalyticsChart.jsx</code> <a class="header-anchor" href="#analyticschart-jsx" aria-label="Permalink to &quot;`AnalyticsChart.jsx`&quot;">​</a></h2><ul><li><strong>Library:</strong> Recharts.</li><li><strong>Usage:</strong> Displays a beautiful, responsive area chart inside the Dashboard showing daily traffic, token burn rate, or active subscribers.</li><li><strong>Styling:</strong> Uses Tailwind classes combined with Recharts&#39; <code>&lt;ResponsiveContainer&gt;</code> to ensure it doesn&#39;t break flex layouts on mobile devices.</li></ul><h2 id="observability-jsx-geminiusage-jsx" tabindex="-1"><code>Observability.jsx</code> &amp; <code>GeminiUsage.jsx</code> <a class="header-anchor" href="#observability-jsx-geminiusage-jsx" aria-label="Permalink to &quot;`Observability.jsx` &amp; `GeminiUsage.jsx`&quot;">​</a></h2><p>These components consume JSON data from the backend representing API call logs and latency metrics.</p><ul><li>They render dynamic Markdown tables.</li><li><strong>Crucial Mobile Rule:</strong> Markdown tables are wrapped in an <code>overflow-x-auto</code> container to prevent them from causing horizontal scrolling (overflow) on mobile viewports.</li></ul><h2 id="factcheckdashboard-jsx" tabindex="-1"><code>FactCheckDashboard.jsx</code> <a class="header-anchor" href="#factcheckdashboard-jsx" aria-label="Permalink to &quot;`FactCheckDashboard.jsx`&quot;">​</a></h2><p>Visualizes the results of <code>FactCheck</code> model runs. Displays confidence scores via color-coded progress bars (Green = High Confidence, Red = Hallucination detected).</p><h2 id="honest-analytics-monetization-system" tabindex="-1"><code>Honest Analytics &amp; Monetization System</code> <a class="header-anchor" href="#honest-analytics-monetization-system" aria-label="Permalink to &quot;`Honest Analytics &amp; Monetization System`&quot;">​</a></h2><ul><li><strong>Bot Filtering</strong>: Employs <code>App\\Services\\BotDetector</code> to filter crawlers, scrapers (curl, python, spoofed UAs), and automated pings into a dedicated crawler breakdown, isolating genuine human traffic in <code>page_views</code> via <code>is_bot = 0</code>.</li><li><strong>Verified Readers</strong>: Marked asynchronously by <code>useEngagementBeacon.js</code> when a user interacts and dwells on an article for &gt;= 4 seconds.</li><li><strong>Engagement Events</strong>: Recorded in <code>engagement_events</code> table for <code>reel_view</code> (requiring &gt;= 2.5s dwell) and <code>ad_view</code>.</li><li><strong>Adsterra Real Revenue</strong>: Integrates with Adsterra API (<code>App\\Services\\AdsterraStatsService</code>) to display actual publisher revenue, impressions, clicks, and eCPM instead of speculative projections.</li></ul>',11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};